+++ b/workspace/sandbox/skills/building-accessible-ui/simple-contact-form--framework-vanilla-js--style-modern--validation-message-present/google/gemini-3-flash-preview__s4/script.js
@@ -1,100 +1,100 @@
 document.addEventListener('DOMContentLoaded', () => {
   const form = document.getElementById('support-form');
   const fields = {
     fullName: {
       input: document.getElementById('full-name'),
       error: document.getElementById('full-name-error'),
       validate: (val) => val.trim() !== '' ? '' : 'Error: Full name is required.'
     },
     email: {
       input: document.getElementById('email'),
       error: document.getElementById('email-error'),
       validate: (val) => {
         if (!val.trim()) return 'Error: Email address is required.';
         const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
         return emailRegex.test(val) ? '' : 'Error: Please enter a valid email address.';
       }
     },
     phone: {
       input: document.getElementById('phone'),
       error: document.getElementById('phone-error'),
       validate: (val) => {
         if (!val.trim()) return ''; // Optional
         // Simple regex for international or US format
         const phoneRegex = /^(\+?\d{1,3}[- ]?)?\(?\d{3}\)?[- ]?\d{3}[- ]?\d{4}$/;
         return phoneRegex.test(val) ? '' : 'Error: Please enter a valid phone number (e.g. +1 555-0123 or (555) 012-3456).';
       }
     }
   };

   const statusMsg = document.getElementById('form-status');

   const updateFieldError = (fieldKey, message) => {
     const field = fields[fieldKey];
     if (message) {
       field.error.textContent = message;
       field.input.setAttribute('aria-invalid', 'true');
       field.input.setAttribute('aria-describedby', field.input.getAttribute('aria-describedby')?.includes(field.error.id) 
         ? field.input.getAttribute('aria-describedby') 
         : `${field.input.getAttribute('aria-describedby') || ''} ${field.error.id}`.trim());
     } else {
       field.error.textContent = '';
       field.input.removeAttribute('aria-invalid');
       // Clean up aria-describedby if error was there
       const descBy = field.input.getAttribute('aria-describedby') || '';
       const cleanedDescBy = descBy.replace(field.error.id, '').trim();
       if (cleanedDescBy) {
         field.input.setAttribute('aria-describedby', cleanedDescBy);
       } else {
         field.input.removeAttribute('aria-describedby');
         // Restore phone helper if applicable
         if (fieldKey === 'phone') {
             field.input.setAttribute('aria-describedby', 'phone-helper');
         }
       }
     }
   };

   // Immediate validation on blur
   Object.keys(fields).forEach(key => {
     fields[key].input.addEventListener('blur', () => {
       const message = fields[key].validate(fields[key].input.value);
       updateFieldError(key, message);
     });
   });

   form.addEventListener('submit', (e) => {
     e.preventDefault();
     let firstInvalid = null;
     let isValid = true;

     Object.keys(fields).forEach(key => {
       const message = fields[key].validate(fields[key].input.value);
       updateFieldError(key, message);
       if (message && isValid) {
         isValid = false;
         firstInvalid = fields[key].input;
       }
     });

     if (!isValid) {
       firstInvalid.focus();
     } else {
       // Simulate submission
       statusMsg.textContent = 'Submitting...';
       statusMsg.className = '';

       setTimeout(() => {
         statusMsg.textContent = 'Thank you! Your message has been sent.';
         statusMsg.className = 'success';
         form.reset();
         // Reset aria-invalid on fields after reset
         Object.keys(fields).forEach(key => {
           fields[key].input.removeAttribute('aria-invalid');
           fields[key].error.textContent = '';
         });
       }, 1000);
     }
   });
 });

