 document.addEventListener('DOMContentLoaded', () => {
   const form = document.getElementById('support-form');
   const fields = {
     fullName: {
       input: document.getElementById('full-name'),
       error: document.getElementById('full-name-error'),
       validate: (val) => val.trim() !== '' ? '' : 'Error: Full name is required.'
     },
     email: {
       input: document.getElementById('email'),
       error: document.getElementById('email-error'),
       validate: (val) => {
         if (!val.trim()) return 'Error: Email address is required.';
         const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
         return emailRegex.test(val) ? '' : 'Error: Please enter a valid email address.';
       }
     },
     phone: {
       input: document.getElementById('phone'),
       error: document.getElementById('phone-error'),
       validate: (val) => {
         if (!val.trim()) return ''; // Optional
         // Simple regex for international or US format
         const phoneRegex = /^(\+?\d{1,3}[- ]?)?\(?\d{3}\)?[- ]?\d{3}[- ]?\d{4}$/;
         return phoneRegex.test(val) ? '' : 'Error: Please enter a valid phone number (e.g. +1 555-0123 or (555) 012-3456).';
       }
     }
   };

   const statusMsg = document.getElementById('form-status');

   const updateFieldError = (fieldKey, message) => {
     const field = fields[fieldKey];
     const input = field.input;
     const error = field.error;

     if (message) {
       error.textContent = message;
       input.setAttribute('aria-invalid', 'true');

       // Ensure error ID is in aria-describedby
       let describedBy = input.getAttribute('aria-describedby') || '';
       if (!describedBy.includes(error.id)) {
         describedBy = `${describedBy} ${error.id}`.trim();
         input.setAttribute('aria-describedby', describedBy);
       }
     } else {
       error.textContent = '';
       input.removeAttribute('aria-invalid');

       // Remove error ID from aria-describedby
       let describedBy = input.getAttribute('aria-describedby') || '';
       if (describedBy.includes(error.id)) {
         describedBy = describedBy.replace(error.id, '').replace(/\s+/g, ' ').trim();
         if (describedBy) {
           input.setAttribute('aria-describedby', describedBy);
         } else {
           input.removeAttribute('aria-describedby');
         }
       }
     }
   };

   // Immediate validation on blur
   Object.keys(fields).forEach(key => {
     fields[key].input.addEventListener('blur', () => {
       const message = fields[key].validate(fields[key].input.value);
       updateFieldError(key, message);
     });
   });

   form.addEventListener('submit', (e) => {
     e.preventDefault();
     let firstInvalid = null;
     let isValid = true;

     Object.keys(fields).forEach(key => {
       const message = fields[key].validate(fields[key].input.value);
       updateFieldError(key, message);
       if (message && isValid) {
         isValid = false;
         firstInvalid = fields[key].input;
       }
     });

     if (!isValid) {
       firstInvalid.focus();
     } else {
       // Simulate submission
       statusMsg.textContent = 'Submitting...';
       statusMsg.className = '';

       setTimeout(() => {
         statusMsg.textContent = 'Thank you! Your message has been sent.';
         statusMsg.className = 'success';
         form.reset();
         // Reset fields
         Object.keys(fields).forEach(key => {
           updateFieldError(key, '');
         });
       }, 1000);
     }
   });
 });

