<body>
    <main>
        <div class="container">
            <h1>Contact Support</h1>
            <p class="description">Have a question? We're here to help. Send us a message and we'll get back to you as soon as possible.</p>

            <p class="required-note"><span aria-hidden="true">*</span> Indicates a required field</p>

            <form id="support-form" novalidate>
                <div class="form-field">
                    <label for="full-name">Full name <span aria-hidden="true">*</span></label>
                    <input type="text" id="full-name" name="fullName" required autocomplete="name" aria-required="true">
                    <div id="full-name-error" class="error-message"></div>
                </div>

                <div class="form-field">
                    <label for="email">Email address <span aria-hidden="true">*</span></label>
                    <input type="email" id="email" name="email" required autocomplete="email" aria-required="true">
                    <div id="email-error" class="error-message"></div>
                </div>

                <div class="form-field">
                    <label for="phone">Phone number (optional)</label>
                    <input type="tel" id="phone" name="phone" autocomplete="tel" aria-describedby="phone-helper">
                    <p id="phone-helper" class="helper-text">Expected format: +1 (555) 000-0000</p>
                    <div id="phone-error" class="error-message"></div>
                </div>

                <button type="submit">Send Message</button>
            </form>

            <div id="form-status" role="status"></div>
        </div>
    </main>
    <script>
        document.addEventListener('DOMContentLoaded', () => {
            const form = document.getElementById('support-form');
            const fields = {
                fullName: {
                    input: document.getElementById('full-name'),
                    error: document.getElementById('full-name-error'),
                    validate: (val) => val.trim() !== '' ? '' : 'Error: Full name is required.'
                },
                email: {
                    input: document.getElementById('email'),
                    error: document.getElementById('email-error'),
                    validate: (val) => {
                        if (!val.trim()) return 'Error: Email address is required.';
                        const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
                        return emailRegex.test(val) ? '' : 'Error: Please enter a valid email address.';
                    }
                },
                phone: {
                    input: document.getElementById('phone'),
                    error: document.getElementById('phone-error'),
                    validate: (val) => {
                        if (!val.trim()) return ''; // Optional
                        const phoneRegex = /^(\+?\d{1,3}[- ]?)?\(?\d{3}\)?[- ]?\d{3}[- ]?\d{4}$/;
                        return phoneRegex.test(val) ? '' : 'Error: Please enter a valid phone number (e.g. +1 555-0123).';
                    }
                }
            };

            const statusMsg = document.getElementById('form-status');

            const updateFieldError = (fieldKey, message) => {
                const field = fields[fieldKey];
                const input = field.input;
                const error = field.error;

                if (message) {
                    error.textContent = message;
                    input.setAttribute('aria-invalid', 'true');

                    let describedBy = input.getAttribute('aria-describedby') || '';
                    if (!describedBy.includes(error.id)) {
                        describedBy = `${describedBy} ${error.id}`.trim();
                        input.setAttribute('aria-describedby', describedBy);
                    }
                } else {
                    error.textContent = '';
                    input.removeAttribute('aria-invalid');

                    let describedBy = input.getAttribute('aria-describedby') || '';
                    if (describedBy.includes(error.id)) {
                        describedBy = describedBy.replace(error.id, '').replace(/\s+/g, ' ').trim();
                        if (describedBy) {
                            input.setAttribute('aria-describedby', describedBy);
                        } else {
                            input.removeAttribute('aria-describedby');
                        }
                    }
                }
            };

            Object.keys(fields).forEach(key => {
                fields[key].input.addEventListener('blur', () => {
                    const message = fields[key].validate(fields[key].input.value);
                    updateFieldError(key, message);
                });
            });

            form.addEventListener('submit', (e) => {
                e.preventDefault();
                let firstInvalid = null;
                let isValid = true;

                Object.keys(fields).forEach(key => {
                    const message = fields[key].validate(fields[key].input.value);
                    updateFieldError(key, message);
                    if (message && isValid) {
                        isValid = false;
                        firstInvalid = fields[key].input;
                    }
                });

                if (!isValid) {
                    firstInvalid.focus();
                } else {
                    statusMsg.textContent = 'Submitting...';
                    statusMsg.className = '';

                    setTimeout(() => {
                        statusMsg.textContent = 'Thank you! Your message has been sent.';
                        statusMsg.className = 'success';
                        form.reset();
                        Object.keys(fields).forEach(key => {
                            updateFieldError(key, '');
                        });
                    }, 1000);
                }
            });
        });
    </script>
